"use strict";(globalThis.webpackChunksap_architecture_center=globalThis.webpackChunksap_architecture_center||[]).push([[550],{50508(e){e.exports=JSON.parse('{"tag":{"label":"Community of Practice","permalink":"/architecture-center/docs/tags/community","description":"A community of practice is a group of people who share a profession or interest and come together to exchange knowledge, solve problems, and sharpen their skills. Grounded in a shared domain, it drives collaboration and continuous learning through shared experiences and resources.","allTagsPath":"/architecture-center/docs/tags","count":31,"items":[{"id":"community/Guidelines/Automated-Checks/readme","title":"Automated Checks for Architecture Center Contributions","description":"A contributor guide to the GitHub Actions checks that run on every SAP Architecture Center pull request, what they verify, and where results appear.","permalink":"/architecture-center/docs/community/automated-checks"},{"id":"community/Guidelines/Automated-Checks/operational-workflows","title":"Build, Deploy, and Security Scanning Workflows","description":"A tour of the background workflows that build and deploy the site to GitHub Pages and Cloudflare, scan for vulnerabilities, and check license compliance.","permalink":"/architecture-center/docs/community/automated-checks/operational-workflows"},{"id":"community/cookie-and-privacy/more","title":"Cloudflare, GitHub and SAP Cookie and Privacy Policies","description":"Links to Cloudflare, GitHub and SAP policies on cookies and privacy, including their cookie notices, privacy statements, and account privacy settings.","permalink":"/architecture-center/docs/community/more-github-sap"},{"id":"community/Guidelines/content-structure","title":"Content Structure for Reference Architectures","description":"Learn how to organize folders, diagrams, images, and documentation for consistency and clarity in your SAP Architecture Center contribution.","permalink":"/architecture-center/docs/community/content-structure"},{"id":"community/Guidelines/GetStarted/get-started-ai-agents","title":"Contributing to the Architecture Center with AI Agents","description":"Use AI coding agents to contribute to the SAP Architecture Center. Learn how AGENTS.md, CLAUDE.md, and skills give agents project context and conventions.","permalink":"/architecture-center/docs/community/get-started-ai-agents"},{"id":"community/intro","title":"Contributing to the SAP Architecture Center","description":"Contribute to the SAP Architecture Center Community of Practice: share reference architectures, follow the contribution process, and co-create with SAP experts.","permalink":"/architecture-center/docs/community/intro"},{"id":"community/cookie-and-privacy/cookie","title":"Cookie Statement | SAP Architecture Center","description":"How the SAP Architecture Center uses cookies and similar technologies, the types of first- and third-party cookies set, and how to manage or delete them.","permalink":"/architecture-center/docs/community/cookie"},{"id":"community/Guidelines/components","title":"Custom Components for Reference Architectures","description":"Learn about the custom Contributors and Draw.io components built for the SAP Architecture Center, and how to use them in your own reference architecture pages.","permalink":"/architecture-center/docs/community/components"},{"id":"community/Guidelines/Automated-Checks/dictionaries","title":"Custom Spelling Dictionaries in the Architecture Center","description":"Learn how the sap, industry, partners, and people dictionaries teach cspell your terms, when to add a word, and how they differ from the typos word list.","permalink":"/architecture-center/docs/community/automated-checks/dictionaries"},{"id":"community/Guidelines/Development/design-and-styling","title":"Design and Styling Guidelines for Contributors","description":"Best practices for CSS, responsive design, and performance in the SAP Architecture Center. Ensure a fast, accessible, and maintainable site.","permalink":"/architecture-center/docs/community/design-and-styling"},{"id":"community/Guidelines/Development/readme","title":"Developer Guidelines for the Architecture Center","description":"Welcome to the development section of the SAP Architecture Center, an open source project with guidelines, best practices, and examples to help you contribute.","permalink":"/architecture-center/docs/community/development"},{"id":"community/Guidelines/diagrams","title":"Draw.io and Mermaid Diagram Best Practices for SAP","description":"Best practices for creating Draw.io diagrams for SAP solution architectures and Mermaid diagrams for process flows in the SAP Architecture Center.","permalink":"/architecture-center/docs/community/diagrams"},{"id":"community/Guidelines/Automated-Checks/check-drawio-files","title":"Draw.io File Checks for Size and External Images","description":"How the drawio check keeps diagram files under one megabyte and blocks external image references, so every diagram stays self-contained and loads reliably.","permalink":"/architecture-center/docs/community/automated-checks/drawio-files"},{"id":"community/Guidelines/Automated-Checks/check-external-links","title":"External Link Check for Broken Links with Lychee","description":"How the external link check uses lychee to verify that outbound links in your changed pages still resolve, and why network issues are reported, not inlined.","permalink":"/architecture-center/docs/community/automated-checks/external-links"},{"id":"community/Guidelines/front-matter","title":"Front Matter Fields for Reference Architectures","description":"Learn how to use front matter in SAP Architecture Center pages. This guide explains each YAML field: title, description, slug, keywords, tags, and more.","permalink":"/architecture-center/docs/community/front-matter"},{"id":"community/Guidelines/Automated-Checks/check-front-matter-properties","title":"Front Matter Properties Check for Reference Architectures","description":"How the front matter properties check validates authorship, dates, and house-style fields on changed reference architecture pages, and why it can block a merge.","permalink":"/architecture-center/docs/community/automated-checks/front-matter-properties"},{"id":"community/Guidelines/Automated-Checks/check-grammar","title":"Grammar and Prose Check with LanguageTool","description":"How the non-blocking LanguageTool grammar check reviews prose in your changed docs and news pages, where its suggestions appear, and why it never fails a PR.","permalink":"/architecture-center/docs/community/automated-checks/grammar"},{"id":"community/Guidelines/Automated-Checks/check-h1-title","title":"H1 Title Check for Reference Architectures","description":"Why Architecture Center pages must take their title from the front matter instead of a level-1 Markdown heading, and how the H1 title check enforces it.","permalink":"/architecture-center/docs/community/automated-checks/h1-title"},{"id":"community/Guidelines/contribution","title":"How to Contribute to SAP Architecture Center","description":"Learn how to contribute to the SAP Architecture Center. Follow step-by-step guidelines for submitting code, documentation, or AI-generated content.","permalink":"/architecture-center/docs/community/contribution"},{"id":"community/Guidelines/Automated-Checks/check-internal-links","title":"Internal Link Check for SAP-Only Hosts in Content","description":"How the internal link check finds SAP-internal-only URLs that break for public visitors, which host patterns it flags, and which customer-facing hosts are safe.","permalink":"/architecture-center/docs/community/automated-checks/internal-links"},{"id":"community/Guidelines/Automated-Checks/check-orphan-files","title":"Orphan Files Check for Unreferenced Assets","description":"How the orphan files check verifies that every image or diagram you add is actually referenced by a Markdown page, and when it warns instead of failing.","permalink":"/architecture-center/docs/community/automated-checks/orphan-files"},{"id":"community/cookie-and-privacy/privacy","title":"Privacy Statement | SAP Architecture Center","description":"How SAP processes your personal data on the SAP Architecture Center, the legal bases, your data protection rights, and country-specific privacy provisions.","permalink":"/architecture-center/docs/community/privacy"},{"id":"community/cookie-and-privacy/quickstart","title":"Quick Start Statement | SAP Architecture Center","description":"How the Quick Start tool uses GitHub OAuth and what personal data it processes to fork repositories, commit changes, and create pull requests on your behalf.","permalink":"/architecture-center/docs/community/quickstart"},{"id":"community/Guidelines/GetStarted/get-started-quickstart","title":"Quick Start: No-Code Architecture Editor","description":"Publish reference architectures with Quick Start, the no-code editor: log in with GitHub, add text and Draw.io diagrams, and submit a pull request.","permalink":"/architecture-center/docs/community/get-started-quickstart"},{"id":"community/Guidelines/Automated-Checks/check-reference-architecture-ids","title":"Reference Architecture ID and Slug Validation Check","description":"How the ID check validates that every reference architecture has a unique six-character id and a matching slug, and what happens when two pages collide.","permalink":"/architecture-center/docs/community/automated-checks/reference-architecture-ids"},{"id":"community/code-of-conduct","title":"SAP Open Source Code of Conduct (Contributor Covenant)","description":"The SAP Open Source Code of Conduct, based on Contributor Covenant 2.1, with community standards, enforcement guidelines, and how to report misconduct.","permalink":"/architecture-center/docs/community/code-of-conduct"},{"id":"community/Guidelines/Automated-Checks/check-seo-front-matter","title":"SEO Front Matter Check for Titles and Descriptions","description":"How the SEO front matter check measures the length of each page title and description, which lengths only warn, and which lengths fail your pull request build.","permalink":"/architecture-center/docs/community/automated-checks/seo-front-matter"},{"id":"community/Guidelines/Automated-Checks/check-spelling","title":"Spelling Check with cspell for Docs and News Pages","description":"How the cspell spelling check scans changed Markdown on your pull request, what it flags as unknown words, and how custom dictionaries keep it quiet.","permalink":"/architecture-center/docs/community/automated-checks/spelling"},{"id":"community/the-team","title":"The Team Behind the SAP Architecture Center","description":"Meet the Office of the CTO and the network of core and extended contributors who build, publish, and govern the SAP Architecture Center.","permalink":"/architecture-center/docs/community/team"},{"id":"community/Guidelines/Automated-Checks/check-typos","title":"Typos Check for Common Misspellings in Markdown","description":"How the typos check catches real misspellings in changed docs and news pages without flagging valid SAP product names, and how to allow a word it corrects.","permalink":"/architecture-center/docs/community/automated-checks/typos"},{"id":"community/Guidelines/Automated-Checks/pr-checks-errors-and-warnings","title":"What Happens When PR Checks Find Errors or Warnings","description":"A worked walkthrough of a pull request: which checks run, where errors and warnings appear, what blocks a merge, and how to read and fix each message.","permalink":"/architecture-center/docs/community/automated-checks/errors-and-warnings"}],"unlisted":false}}')}}]);